namespace {
QString impactValue(QJsonValue v){if(v.isDouble())return QString::number(v.toDouble(),'g',12);if(v.isString())return v.toString();if(v.isNull()||v.isUndefined())return QObject::tr("없음");if(v.isBool())return v.toBool()?"true":"false";return QString::fromUtf8(v.isArray()?QJsonDocument(v.toArray()).toJson(QJsonDocument::Compact):QJsonDocument(v.toObject()).toJson(QJsonDocument::Compact));}
QString impactStatus(QString s){if(s=="failed")return QObject::tr("도달 / 실행 실패");if(s=="changed")return QObject::tr("변화 있음");if(s=="unchanged")return QObject::tr("동일");if(s=="missing-baseline")return QObject::tr("기준 없음");if(s=="incomplete")return QObject::tr("미완료");return QObject::tr("검사 오류");}
QString impactKinds(QJsonObject row){auto f=row.value("flags").toObject();QStringList out;if(row.value("valueChangeCount").toInt())out<<QObject::tr("능력·자원 %1개").arg(row.value("valueChangeCount").toInt());for(const auto& p:QList<QPair<QString,QString>>{{"costChanged",QObject::tr("비용")},{"effectsChanged",QObject::tr("효과")},{"conditionsChanged",QObject::tr("조건")},{"routeChanged",QObject::tr("경로 명령/시작 조건")},{"runtimeChanged",QObject::tr("런타임")}})if(f.value(p.first).toBool())out<<p.second;if(out.isEmpty()&&f.value("stateChanged").toBool())out<<QObject::tr("실행 상태");return out.join(" · ");}
}
void StudioWindow::acceptGoalImpact(QJsonObject report){
  report["viewRevision"]=view.value("revision");lastGoalImpact=report;
  log->appendPlainText(tr("저장 기준 비교: %1개 경로 · 실패 %2 · 변화 %3").arg(report.value("rows").toArray().size()).arg(report.value("counts").toObject().value("failed").toInt()).arg(report.value("counts").toObject().value("changed").toInt()));
  if(!report.value("rows").toArray().isEmpty()||report.contains("error"))goalImpactDialog(report);
  emit goalImpactReady(report);
}
